"184 :   @Override
185 :   JSType resolveInternal(ErrorReporter t, StaticScope<JSType> enclosing) {
186 :     // TODO(user): Investigate whether it is really necessary to keep two
187 :     // different mechanisms for resolving named types, and if so, which order
188 :     // makes more sense. Now, resolution via registry is first in order to
189 :     // avoid triggering the warnings built into the resolution via properties.
190 :     boolean resolved = resolveViaRegistry(t, enclosing);
191 :     if (detectImplicitPrototypeCycle()) {
192 :       handleTypeCycle(t);
193 :     }
194 : 
195 :     if (resolved) {
196 :       super.resolveInternal(t, enclosing);
197 :       return registry.isLastGeneration() ?
198 :           getReferencedType() : this;
199 :     }
200 : 
201 :     resolveViaProperties(t, enclosing);
202 :     if (detectImplicitPrototypeCycle()) {
203 :       handleTypeCycle(t);
204 :     }
205 : 
206 :     super.resolveInternal(t, enclosing);
207 :     return registry.isLastGeneration() ?
208 :         getReferencedType() : this;
209 :   }"

